package com.noircipher.shade.engine

import java.security.MessageDigest

/**
 * Suggestion-level profanity suppression — the engine behind the
 * "block offensive words" toggle.
 *
 * The word list ships as 64-bit truncated SHA-256 hashes
 * (assets/dicts/en_offensive.txt, generated by
 * scripts/gen_offensive_hashes.py from a curated base set plus regular
 * inflections) instead of plaintext: the APK carries no slur strings, but
 * the filter still matches EXACT word forms only. No prefix rules — so a
 * word that merely starts with or contains a blocked form ("asset",
 * "class", "shift", "buttress") can never be suppressed by accident.
 *
 * Contract: the filter never alters user text. When the user types an
 * offensive word themselves it is committed as typed; the filter only
 * removes it from what Shade SUGGESTS or AUTO-CORRECTS to.
 *
 * Kept free of Android types so it can be unit-tested on the JVM; the
 * service loads the asset and flips [enabled] from the prefs.
 */
object ProfanityFilter {

    @Volatile
    var enabled: Boolean = true

    @Volatile
    private var hashes: Set<String> = emptySet()

    /** Number of loaded hashes; 0 = filter inert (asset missing or empty). */
    val loadedCount: Int get() = hashes.size

    /**
     * Loads hex hash lines (one 16-char lowercase hex token per line).
     * Comment lines and malformed lines are ignored, so a truncated or
     * hand-edited asset can never crash the keyboard.
     */
    fun load(lines: Sequence<String>) {
        hashes = lines.map { it.trim() }
            .filter { it.length == 16 && it.all { c -> c in '0'..'9' || c in 'a'..'f' } }
            .toSet()
    }

    fun isOffensive(word: String): Boolean {
        if (!enabled || hashes.isEmpty()) return false
        val w = word.trim().lowercase()
        // Exact alphabetic forms only: nothing to match in short tokens,
        // numbers, or anything with punctuation inside.
        if (w.length < 3 || !w.all { it in 'a'..'z' }) return false
        return sha16(w) in hashes
    }

    /** First 64 bits of SHA-256 as lowercase hex — the asset's word format. */
    fun sha16(word: String): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(word.toByteArray(Charsets.UTF_8))
        return digest.take(8).joinToString("") { "%02x".format(it) }
    }
}
